export function getAllAhzab(): HizbData[] {
  return ALL_AHZAB;
}

export function getHizbByNumber(hizbNum: number): HizbData | undefined {
  return ALL_AHZAB.find(h => h.number === hizbNum);
}

export function getThumunById(thumunId: number): ThumunItem | undefined {
  for (const h of ALL_AHZAB) {
    const found = h.thumuns.find(t => t.id === thumunId);
    if (found) return found;
  }
  return undefined;
}
